#define PII pair<int, int>
#define MP make_pair
#define A b * 1.0 * (1.0 - dfs(b - 1, a)) / (b * 1.0 + 1.0)
#define B 1
#define C (1.0 + 1.0 * b * (1.0 - dfs(b - 1, a))) / (b * 1.0 + 1.0)
#define D (1.0 - dfs(b, a - 1))
#define P (D - B) / (A - B - C + D)

