inline double dfs(int a, int b)
{
    if (b == 0)
    {
        return 1.0;
    }
    if (a == 0)
    {
        return 1.0 / (1.0 * b + 1.0);
    }
    if (m.count(MP(a, b)))
    {
        return m[MP(a, b)];
    }
    double ans = P * A + (1.0 - P) * B;
    m[MP(a, b)] = ans;
    return ans;
}

