    printf("%.9lf %.9lf", ans, 1.0 - ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using PII = pair<int, int>;

map<PII, double> memo;

double dfs(int a, int b) {
    if (b == 0) return 1.0;
    if (a == 0) return 1.0 / (b + 1.0);

    PII state = {a, b};
    auto it = memo.find(state);
    if (it != memo.end()) return it->second;

    double previous = dfs(b - 1, a);
    double A = b * (1.0 - previous) / (b + 1.0);
    double B = 1.0;
    double C = (1.0 + b * (1.0 - previous)) / (b + 1.0);
    double D = 1.0 - dfs(b, a - 1);
    double P = (D - B) / (A - B - C + D);

    double ans = P * A + (1.0 - P) * B;
    memo[state] = ans;
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b;
    cin >> a >> b;

    double ans = dfs(a, b);
    cout << fixed << setprecision(9) << ans << ' ' << 1.0 - ans;
    return 0;
}

